import java.util.*;

public class MemoryShape {
    public static void main(String[] args) {
        // ArrayList: backing array of references, contiguous
        // [ref0][ref1][ref2]...  + spare capacity
        List<String> arr = new ArrayList<>(1000);  // pre-sized: minimal waste

        // LinkedList: each add allocates a Node:
        //   class Node<E> { E item; Node<E> next; Node<E> prev; }
        // = value ref + 2 pointers + object header per element
        List<String> lnk = new LinkedList<>();
        for (int i = 0; i < 1000; i++) lnk.add("v" + i);

        // Iteration: ArrayList streams through contiguous memory (cache-friendly);
        // LinkedList chases pointers across the heap (cache-hostile).
        long count = arr.stream().count();
    }
}
```

