import java.util.*;

public class QueueWorkload {
    public static void main(String[] args) {
        // FIFO queue: O(1) at both ends on LinkedList
        Queue<String> q = new LinkedList<>();
        q.offer("job-1");        // add at tail - O(1)
        q.offer("job-2");
        String next = q.poll();  // remove from head - O(1)

        // ArrayList as a queue would be O(n) per front removal:
        List<String> bad = new ArrayList<>(List.of("a", "b", "c"));
        bad.remove(0);           // shifts everything left - O(n)

        // Best in practice for queues/stacks: ArrayDeque
        Deque<String> dq = new ArrayDeque<>();
        dq.addLast("x");
        dq.pollFirst();          // O(1), cache-friendly, less memory
    }
}
```

